import sys,json,hashlib
sys.path.insert(0,'tools/ParityRunner');from adjudicate_background import ROOT,read,update
va=read('VA.address-resolver.resolve-name.json');assert 'PdbTarget103' in va['result']['output'];ca=read('CA.address-resolver.output-tree.json');assert any('PdbTarget103' in str(x.get('value')) and len(str(x.get('value')))<500 for x in ca);bad=read('CA.address-resolver.module-relative.output-tree.json');assert any(x['name']=='Invalid RVA' for x in bad)
(ROOT/'VA.address-resolver.bundle.json').write_text(json.dumps(dict(fixture=read('pdb-fixture.json'),resolve=va),ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/'CA.address-resolver.bundle.json').write_text(json.dumps(dict(fixture=read('pdb-fixture.json'),rvaOutput=[x for x in ca if x['type']=='ControlType.Edit' and 'PdbTarget103' in str(x.get('value')) and len(str(x.get('value')))<500],moduleRelativeError=[x for x in bad if x['name']=='Invalid RVA'],sourceFiles={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest() for n in ['CA.address-resolver.output-tree.json','CA.address-resolver.module-relative.output-tree.json']}),ensure_ascii=False,indent=2),encoding='utf-8')
update(89,'different','자체 EXE/PDB의 RVA 0x1000을 양쪽 모두 PdbTarget103으로 해석했습니다. VA는 PdbAudit103+0x1000 형식도 해석하지만 CA는 같은 모듈 상대주소 문자열에 Invalid RVA를 표시합니다. 단일 함수 해석 성공과 입력 형식 범위 차이를 분리했습니다.',{'VA':'VA.address-resolver.bundle.json','CA':'CA.address-resolver.bundle.json'},{'targetAtSameRvaBoth':True,'moduleRelativeFormatSupportedBoth':False})
update(14,'different','실제 편집기 탐색 표시에서 VA 문맥·정의 필드는 콤보박스이고 CA 대응 필드는 정적 텍스트입니다. 지역 변수의 문맥 계층과 초기화식 표시도 다릅니다. 이 판정은 해당 탐색 표시 구성의 차이이며 탐색 막대 전체 동작 인증은 아닙니다.',{'VA':'VA.context-dte.bundle.json','CA':'CA.context-dte.bundle.json'},{'sameInputMemberLocalUnknown':True,'contextAndDefinitionWidgetTypesEqual':False})
